/**
 * Unicode helpers that mirror the character classifications CPython relies on.
 *
 * Only the pieces this project needs are implemented:
 *   - the whitespace set used by `str.strip()` / the `int()` constructor
 *   - decimal digit values for the whole `Nd` category (`int("１２") == 12`)
 *   - `str.isprintable()`, used by `repr()` when escaping error messages
 */

/**
 * Characters for which CPython's `Py_UNICODE_ISSPACE` is true. This is the set
 * stripped from both ends of the string handed to `int()`.
 */
const WHITESPACE = new Set([
  0x09, 0x0a, 0x0b, 0x0c, 0x0d, 0x1c, 0x1d, 0x1e, 0x1f, 0x20,
  0x85, 0xa0, 0x1680, 0x2000, 0x2001, 0x2002, 0x2003, 0x2004, 0x2005,
  0x2006, 0x2007, 0x2008, 0x2009, 0x200a, 0x2028, 0x2029, 0x202f,
  0x205f, 0x3000,
]);

const DECIMAL_DIGIT = /^\p{Nd}$/u;
const NOT_PRINTABLE = /^[\p{Cc}\p{Cf}\p{Cs}\p{Co}\p{Cn}\p{Zl}\p{Zp}\p{Zs}]$/u;

export function isPythonSpace(ch) {
  return WHITESPACE.has(ch.codePointAt(0));
}

/** Equivalent of `str.strip()` with no argument. */
export function pythonStrip(s) {
  const chars = Array.from(s);
  let start = 0;
  let end = chars.length;
  while (start < end && isPythonSpace(chars[start])) start += 1;
  while (end > start && isPythonSpace(chars[end - 1])) end -= 1;
  return chars.slice(start, end).join('');
}

/**
 * Numeric value 0-9 of a decimal digit, or -1 when the character is not in the
 * `Nd` category.
 *
 * ASCII is handled directly. Compatibility digits (full width, mathematical
 * styles, ...) decompose to ASCII under NFKC. Everything else -- Arabic-Indic,
 * Devanagari and friends -- lives in a contiguous run of ten code points whose
 * first member is the zero of that script, so counting downwards recovers the
 * value.
 */
export function decimalDigitValue(ch) {
  const cp = ch.codePointAt(0);
  if (cp >= 0x30 && cp <= 0x39) return cp - 0x30;
  if (!DECIMAL_DIGIT.test(ch)) return -1;

  const folded = ch.normalize('NFKC');
  if (folded.length === 1) {
    const foldedCp = folded.codePointAt(0);
    if (foldedCp >= 0x30 && foldedCp <= 0x39) return foldedCp - 0x30;
  }

  let value = 0;
  while (value < 9 && DECIMAL_DIGIT.test(String.fromCodePoint(cp - value - 1))) {
    value += 1;
  }
  return value;
}

/** Equivalent of `str.isprintable()` for a single character. */
export function isPrintable(ch) {
  if (ch === ' ') return true;
  return !NOT_PRINTABLE.test(ch);
}

