/**
 * Reimplementation of the handful of Python builtins this program depends on:
 * `int()`, `repr()` for strings, `print()` and the textual form of `bool`.
 */

import { ValueError } from './errors.mjs';
import { decimalDigitValue, isPrintable, pythonStrip } from './unicode.mjs';

/**
 * `int(s)` for a string argument, returning a BigInt so that node identity
 * stays exact for values beyond 2**53.
 *
 * Accepts surrounding whitespace, an optional sign, any Unicode decimal digits
 * and single underscores between digits -- and nothing else. No `0x` prefixes,
 * no decimal points, no exponents.
 */
export function pyInt(text) {
  const stripped = pythonStrip(String(text));
  const chars = Array.from(stripped);

  let index = 0;
  let sign = '';
  if (chars[index] === '+' || chars[index] === '-') {
    sign = chars[index] === '-' ? '-' : '';
    index += 1;
  }

  let digits = '';
  let previousWasDigit = false;
  for (; index < chars.length; index += 1) {
    const ch = chars[index];
    if (ch === '_') {
      // Underscores are separators: they must sit between two digits.
      if (!previousWasDigit) throw new ValueError(invalidLiteral(text));
      previousWasDigit = false;
      continue;
    }
    const value = decimalDigitValue(ch);
    if (value < 0) throw new ValueError(invalidLiteral(text));
    digits += String(value);
    previousWasDigit = true;
  }

  if (!previousWasDigit) throw new ValueError(invalidLiteral(text));
  return BigInt(sign + digits);
}
Object.defineProperty(pyInt, 'pyName', { value: 'int' });

function invalidLiteral(text) {
  return `invalid literal for int() with base 10: ${pyRepr(text)}`;
}

const SHORT_ESCAPES = new Map([
  ['\\', '\\\\'],
  ['\n', '\\n'],
  ['\r', '\\r'],
  ['\t', '\\t'],
]);

/**
 * `repr()` of a string: single quotes unless the value contains a single quote
 * and no double quote, with non-printable characters escaped the way CPython
 * escapes them.
 */
export function pyRepr(value) {
  const text = String(value);
  const quote = text.includes("'") && !text.includes('"') ? '"' : "'";

  let out = quote;
  for (const ch of text) {
    const short = SHORT_ESCAPES.get(ch);
    if (short !== undefined) {
      out += short;
    } else if (ch === quote) {
      out += '\\' + ch;
    } else if (isPrintable(ch)) {
      out += ch;
    } else {
      out += escapeCodePoint(ch.codePointAt(0));
    }
  }
  return out + quote;
}

function escapeCodePoint(cp) {
  if (cp <= 0xff) return '\\x' + cp.toString(16).padStart(2, '0');
  if (cp <= 0xffff) return '\\u' + cp.toString(16).padStart(4, '0');
  return '\\U' + cp.toString(16).padStart(8, '0');
}

/** `str()` of a bool: `True` / `False`. */
export function pyBool(value) {
  return value ? 'True' : 'False';
}

/** `print()` -- writes to stdout followed by a newline. */
export function print(...values) {
  process.stdout.write(values.join(' ') + '\n');
}

