/**
 * `textwrap.wrap()` for the single-paragraph, already-collapsed text the help
 * formatter feeds it.
 */

/** Collapse every run of whitespace to a single space and trim the ends. */
export function collapseWhitespace(text) {
  return text.replace(/[\t\n\v\f\r ]+/g, ' ').trim();
}

/**
 * Greedy wrap at `width` columns. Words longer than the whole line are broken,
 * matching textwrap's default `break_long_words=True`.
 */
export function wrap(text, width) {
  const limit = Math.max(1, width);
  const lines = [];
  let line = '';

  for (const word of collapseWhitespace(text).split(' ')) {
    if (!word) continue;
    let remaining = word;

    if (line && line.length + 1 + remaining.length <= limit) {
      line += ' ' + remaining;
      continue;
    }
    if (line) {
      lines.push(line);
      line = '';
    }
    while (remaining.length > limit) {
      lines.push(remaining.slice(0, limit));
      remaining = remaining.slice(limit);
    }
    line = remaining;
  }

  if (line) lines.push(line);
  return lines;
}

