/** Error types raised inside the argument parser. */

export class ArgumentError extends Error {
  constructor(action, message) {
    const name = action ? argumentName(action) : null;
    super(name === null ? message : `argument ${name}: ${message}`);
    this.name = 'ArgumentError';
    this.action = action;
  }
}

/** Thrown by the help action; unwinds the parse so the process can exit. */
export class ParserExit extends Error {
  constructor(status, message) {
    super(message ?? '');
    this.name = 'ParserExit';
    this.status = status;
    this.output = message;
  }
}

/** `argparse._get_action_name()`: the first option string, or the metavar. */
export function argumentName(action) {
  if (action.optionStrings.length > 0) return action.optionStrings[0];
  if (action.metavar !== undefined && action.metavar !== null) return action.metavar;
  if (action.dest !== undefined && action.dest !== '--') return action.dest;
  return null;
}

