/**
 * Terminal width discovery, mirroring `shutil.get_terminal_size()` as used by
 * argparse (`columns - 2`).
 */

import { pyInt } from '../python/builtins.mjs';

const FALLBACK_COLUMNS = 80;

export function terminalColumns() {
  let columns = 0;

  const env = process.env.COLUMNS;
  if (env !== undefined) {
    try {
      columns = Number(pyInt(env));
    } catch {
      columns = 0;
    }
  }

  if (columns <= 0) {
    const stdoutColumns = process.stdout && process.stdout.columns;
    columns = stdoutColumns > 0 ? stdoutColumns : FALLBACK_COLUMNS;
  }

  return columns;
}

