/**
 * Actions -- the objects created by `add_argument()`. Only the two behaviours
 * this program uses are implemented: `store` and `help`.
 */

import { ParserExit } from './errors.mjs';

export class StoreAction {
  constructor({ optionStrings, dest, type, required, help, metavar }) {
    this.optionStrings = optionStrings;
    this.dest = dest;
    this.type = type ?? null;
    this.nargs = null;
    this.required = Boolean(required);
    this.help = help ?? null;
    this.metavar = metavar ?? null;
  }

  call(parser, namespace, value) {
    namespace[this.dest] = value;
  }
}

export class HelpAction {
  constructor({ optionStrings, dest, help }) {
    this.optionStrings = optionStrings;
    this.dest = dest;
    this.type = null;
    this.nargs = 0;
    this.required = false;
    this.help = help ?? null;
    this.metavar = null;
  }

  call(parser) {
    throw new ParserExit(0, parser.formatHelp());
  }
}

