/**
 * A faithful subset of `argparse.ArgumentParser`: long/short options, `=`
 * attached values, prefix abbreviation, the `--` separator, required-argument
 * checking, `-h/--help`, and the exact error text and exit codes CPython emits.
 */

import { basename } from 'node:path';

import { pyRepr } from '../python/builtins.mjs';
import { ValueError } from '../python/errors.mjs';
import { HelpAction, StoreAction } from './actions.mjs';
import { ArgumentError, ParserExit, argumentName } from './errors.mjs';
import { HelpFormatter } from './help-formatter.mjs';

const NEGATIVE_NUMBER = /^-\d+$|^-\d*\.\d+$/;

export class ArgumentParser {
  constructor({ prog, addHelp = true } = {}) {
    this.prog = prog ?? defaultProg();
    this.allowAbbrev = true;
    this._actions = [];
    this._optionStringActions = new Map();
    this._hasNegativeNumberOptionals = false;

    if (addHelp) {
      this.addArgument(['-h', '--help'], {
        action: 'help',
        help: 'show this help message and exit',
      });
    }
  }

  addArgument(optionStrings, options = {}) {
    const strings = Array.isArray(optionStrings) ? optionStrings : [optionStrings];
    const dest = options.dest ?? destFromOptionStrings(strings);
    const spec = { ...options, optionStrings: strings, dest };
    const action = options.action === 'help'
      ? new HelpAction(spec)
      : new StoreAction(spec);

    this._actions.push(action);
    for (const optionString of strings) {
      this._optionStringActions.set(optionString, action);
      if (NEGATIVE_NUMBER.test(optionString)) this._hasNegativeNumberOptionals = true;
    }
    return action;
  }

  parseArgs(argv) {
    const [namespace, extras] = this.parseKnownArgs(argv);
    if (extras.length > 0) {
      this.error(`unrecognized arguments: ${extras.join(' ')}`);
    }
    return namespace;
  }

  parseKnownArgs(argv = process.argv.slice(2)) {
    const namespace = Object.create(null);
    for (const action of this._actions) {
      if (!(action instanceof HelpAction)) namespace[action.dest] = null;
    }

    const seen = new Set();
    const extras = [];
    let index = 0;
    let afterSeparator = false;

    try {
      while (index < argv.length) {
        const argString = argv[index];

        // Everything from `--` onwards stops being an option, including the
        // separator itself -- with no positionals declared it all falls
        // through to the unrecognized-arguments report.
        if (afterSeparator || argString === '--') {
          afterSeparator = true;
          extras.push(argString);
          index += 1;
          continue;
        }

        const option = this._parseOptional(argString);
        if (option === null || option.action === null) {
          extras.push(argString);
          index += 1;
          continue;
        }

        const { action, optionString, explicitArg } = option;
        seen.add(action);

        if (action.nargs === 0) {
          if (explicitArg !== null) {
            throw new ArgumentError(
              action,
              `ignored explicit argument ${pyRepr(explicitArg)}`,
            );
          }
          action.call(this, namespace, undefined, optionString);
          index += 1;
          continue;
        }

        let rawValue;
        if (explicitArg !== null) {
          rawValue = explicitArg;
          index += 1;
        } else {
          const next = argv[index + 1];
          if (next === undefined || this._parseOptional(next) !== null) {
            throw new ArgumentError(action, 'expected one argument');
          }
          rawValue = next;
          index += 2;
        }
        action.call(this, namespace, this._getValue(action, rawValue), optionString);
      }
    } catch (err) {
      if (err instanceof ArgumentError) this.error(err.message);
      throw err;
    }

    const missing = this._actions
      .filter((action) => action.required && !seen.has(action))
      .map((action) => argumentName(action));
    if (missing.length > 0) {
      this.error(`the following arguments are required: ${missing.join(', ')}`);
    }

    return [namespace, extras];
  }

  /**
   * Classify one command-line token. Returns `null` when it is not an option,
   * or a tuple whose `action` is `null` for an unknown option.
   */
  _parseOptional(argString) {
    if (!argString) return null;
    if (argString[0] !== '-') return null;

    const exact = this._optionStringActions.get(argString);
    if (exact !== undefined) {
      return { action: exact, optionString: argString, explicitArg: null };
    }
    if (argString.length === 1) return null;

    const equals = argString.indexOf('=');
    if (equals !== -1) {
      const optionString = argString.slice(0, equals);
      const action = this._optionStringActions.get(optionString);
      if (action !== undefined) {
        return { action, optionString, explicitArg: argString.slice(equals + 1) };
      }
    }

    const matches = this._getOptionTuples(argString);
    if (matches.length > 1) {
      const options = matches.map((match) => match.optionString).join(', ');
      this.error(`ambiguous option: ${argString} could match ${options}`);
    }
    if (matches.length === 1) return matches[0];

    if (NEGATIVE_NUMBER.test(argString) && !this._hasNegativeNumberOptionals) {
      return null;
    }
    if (argString.includes(' ')) return null;

    return { action: null, optionString: argString, explicitArg: null };
  }

  /** Abbreviated long options, plus short options with an attached value. */
  _getOptionTuples(argString) {
    const result = [];

    if (argString.startsWith('--')) {
      if (!this.allowAbbrev) return result;
      const equals = argString.indexOf('=');
      const optionPrefix = equals === -1 ? argString : argString.slice(0, equals);
      const explicitArg = equals === -1 ? null : argString.slice(equals + 1);
      for (const [optionString, action] of this._optionStringActions) {
        if (optionString.startsWith(optionPrefix)) {
          result.push({ action, optionString, explicitArg });
        }
      }
      return result;
    }

    const shortPrefix = argString.slice(0, 2);
    const shortExplicitArg = argString.slice(2);
    for (const [optionString, action] of this._optionStringActions) {
      if (optionString === shortPrefix) {
        result.push({ action, optionString, explicitArg: shortExplicitArg });
      } else if (this.allowAbbrev && optionString.startsWith(argString)) {
        result.push({ action, optionString, explicitArg: null });
      }
    }
    return result;
  }

  _getValue(action, argString) {
    if (!action.type) return argString;
    try {
      return action.type(argString);
    } catch (err) {
      if (!(err instanceof ValueError)) throw err;
      const typeName = action.type.pyName ?? action.type.name;
      throw new ArgumentError(
        action,
        `invalid ${typeName} value: ${pyRepr(argString)}`,
      );
    }
  }

  formatUsage() {
    return stripTrailingBlank(new HelpFormatter(this.prog).formatUsage(this._actions));
  }

  formatHelp() {
    return new HelpFormatter(this.prog).formatHelp(this._actions);
  }

  printUsage(stream = process.stdout) {
    stream.write(this.formatUsage());
  }

  printHelp(stream = process.stdout) {
    stream.write(this.formatHelp());
  }

  error(message) {
    this.printUsage(process.stderr);
    this.exit(2, `${this.prog}: error: ${message}\n`);
  }

  exit(status = 0, message = null) {
    if (message) process.stderr.write(message);
    throw new ParserExit(status, message);
  }
}

function destFromOptionStrings(optionStrings) {
  const longOption = optionStrings.find((option) => option.startsWith('--'));
  const chosen = longOption ?? optionStrings[0];
  return chosen.replace(/^-+/, '').replace(/-/g, '_');
}

/** argparse's default prog: the basename of the script that was invoked. */
function defaultProg() {
  return basename(process.argv[1] ?? 'node');
}

/** `format_usage()` collapses the trailing blank line the formatter emits. */
function stripTrailingBlank(usage) {
  return usage.replace(/\n+$/, '') + '\n';
}

