/**
 * Node identity, standing in for Python's hashing rules.
 *
 * Graph nodes are dict keys in networkx, so two nodes are the same node when
 * they are equal in Python. Integers arrive here as BigInt to keep values past
 * 2**53 distinct, and `-0` folds into `0` exactly as it does in Python.
 */

export function nodeKey(node) {
  switch (typeof node) {
    case 'bigint':
      return `i:${node.toString()}`;
    case 'boolean':
      return `i:${node ? '1' : '0'}`;
    case 'number':
      return Number.isInteger(node)
        ? `i:${BigInt(node).toString()}`
        : `f:${node}`;
    case 'string':
      return `s:${node}`;
    case 'object':
      if (node === null) return 'n:';
      break;
    default:
      break;
  }
  return `o:${String(node)}`;
}

