/**
 * Directed graph, the subset of `networkx.DiGraph` this program touches.
 *
 * Adjacency is stored the way networkx does it -- successor and predecessor
 * maps keyed by node -- with insertion order preserved, since that is what
 * makes traversal output reproducible.
 */

import { nodeKey } from './node-key.mjs';

export class DiGraph {
  constructor() {
    this._node = new Map(); // key -> node value
    this._succ = new Map(); // key -> Map(key -> attributes)
    this._pred = new Map(); // key -> Map(key -> attributes)
  }

  isDirected() {
    return true;
  }

  isMultigraph() {
    return false;
  }

  addNode(node) {
    const key = nodeKey(node);
    if (!this._node.has(key)) {
      this._node.set(key, node);
      this._succ.set(key, new Map());
      this._pred.set(key, new Map());
    }
    return key;
  }

  addNodesFrom(nodes) {
    for (const node of nodes) this.addNode(node);
  }

  addEdge(u, v, attributes = {}) {
    const uKey = this.addNode(u);
    const vKey = this.addNode(v);
    const existing = this._succ.get(uKey).get(vKey) ?? {};
    const merged = Object.assign(existing, attributes);
    this._succ.get(uKey).set(vKey, merged);
    this._pred.get(vKey).set(uKey, merged);
  }

  /** `G.add_edges_from([(u, v), ...])`. */
  addEdgesFrom(edges) {
    for (const edge of edges) {
      const [u, v, attributes] = edge;
      this.addEdge(u, v, attributes ?? {});
    }
  }

  hasNode(node) {
    return this._node.has(nodeKey(node));
  }

  hasEdge(u, v) {
    const successors = this._succ.get(nodeKey(u));
    return successors !== undefined && successors.has(nodeKey(v));
  }

  /** Node values, in insertion order. */
  nodes() {
    return this._node.values();
  }

  numberOfNodes() {
    return this._node.size;
  }

  numberOfEdges() {
    let total = 0;
    for (const successors of this._succ.values()) total += successors.size;
    return total;
  }

  *successors(node) {
    const successors = this._succ.get(nodeKey(node));
    if (successors === undefined) return;
    for (const key of successors.keys()) yield this._node.get(key);
  }

  *predecessors(node) {
    const predecessors = this._pred.get(nodeKey(node));
    if (predecessors === undefined) return;
    for (const key of predecessors.keys()) yield this._node.get(key);
  }

  inDegree(node) {
    const predecessors = this._pred.get(nodeKey(node));
    return predecessors === undefined ? 0 : predecessors.size;
  }

  outDegree(node) {
    const successors = this._succ.get(nodeKey(node));
    return successors === undefined ? 0 : successors.size;
  }

  /** Internal adjacency view used by the algorithms module. */
  adjacencyKeys() {
    return this._succ;
  }

  nodeKeys() {
    return this._node;
  }
}

