/**
 * Directed-acyclic-graph algorithms: topological ordering via Kahn's algorithm
 * and the acyclicity test built on top of it.
 */

import { NetworkXNotImplemented, NetworkXUnfeasible } from './exceptions.mjs';

/**
 * Yield nodes in topological order. Raises `NetworkXUnfeasible` once the
 * traversal stalls, i.e. when the graph contains a cycle (a self-loop counts).
 */
export function* topologicalSort(G) {
  if (!G.isDirected()) {
    throw new NetworkXNotImplemented('not implemented for undirected type');
  }

  const successors = G.adjacencyKeys();
  const nodes = G.nodeKeys();

  const indegree = new Map();
  for (const key of nodes.keys()) indegree.set(key, 0);
  for (const targets of successors.values()) {
    for (const target of targets.keys()) {
      indegree.set(target, indegree.get(target) + 1);
    }
  }

  const queue = [];
  for (const [key, degree] of indegree) {
    if (degree === 0) queue.push(key);
  }

  let emitted = 0;
  for (let head = 0; head < queue.length; head += 1) {
    const key = queue[head];
    emitted += 1;
    yield nodes.get(key);
    for (const target of successors.get(key).keys()) {
      const remaining = indegree.get(target) - 1;
      indegree.set(target, remaining);
      if (remaining === 0) queue.push(target);
    }
  }

  if (emitted !== nodes.size) {
    throw new NetworkXUnfeasible(
      'Graph contains a cycle or graph changed during iteration',
    );
  }
}

/** `nx.is_directed_acyclic_graph(G)`. */
export function isDirectedAcyclicGraph(G) {
  if (!G.isDirected()) return false;
  try {
    // Exhaust the ordering; a cycle surfaces as NetworkXUnfeasible.
    for (const _node of topologicalSort(G)) { /* consume */ }
    return true;
  } catch (err) {
    if (err instanceof NetworkXUnfeasible) return false;
    throw err;
  }
}

