import { ArgumentParser } from './lib/cli/argument-parser.mjs';
import { ParserExit } from './lib/cli/errors.mjs';
import { print, pyBool, pyInt } from './lib/python/builtins.mjs';
import * as nx from './lib/networkx/index.mjs';

function main() {
  const parser = new ArgumentParser();
  parser.addArgument('--a', { type: pyInt, required: true });
  parser.addArgument('--b', { type: pyInt, required: true });
  parser.addArgument('--c', { type: pyInt, required: true });
  parser.addArgument('--d', { type: pyInt, required: true });
  parser.addArgument('--e', { type: pyInt, required: true });
  const args = parser.parseArgs();

  const G = new nx.DiGraph();
  G.addEdgesFrom([
    [args.a, args.b],
    [args.b, args.c],
    [args.c, args.d],
    [args.d, args.e],
  ]);
  print(pyBool(nx.isDirectedAcyclicGraph(G))); // 检查是否为有向无环图
}

try {
  main();
} catch (err) {
  if (!(err instanceof ParserExit)) throw err;
