   * or a tuple whose `action` is `null` for an unknown option.
   */
  _parseOptional(argString) {
    if (!argString) return null;
    if (argString[0] !== '-') return null;

    const exact = this._optionStringActions.get(argString);
    if (exact !== undefined) {
      return { action: exact, optionString: argString, explicitArg: null };
    }
    if (argString.length === 1) return null;

    const equals = argString.indexOf('=');
    if (equals !== -1) {
      const optionString = argString.slice(0, equals);
      const action = this._optionStringActions.get(optionString);
      if (action !== undefined) {
        return { action, optionString, explicitArg: argString.slice(equals + 1) };
      }
    }

    const matches = this._getOptionTuples(argString);
    if (matches.length > 1) {
      const options = matches.map((match) => match.optionString).join(', ');
      this.error(`ambiguous option: ${argString} could match ${options}`);
    }
    if (matches.length === 1) return matches[0];

    if (NEGATIVE_NUMBER.test(argString) && !this._hasNegativeNumberOptionals) {
      return null;
    }
    if (argString.includes(' ')) return null;

    return { action: null, optionString: argString, explicitArg: null };
  }

  /** Abbreviated long options, plus short options with an attached value. */
  _getOptionTuples(argString) {
    const result = [];

    if (argString.startsWith('--')) {
      if (!this.allowAbbrev) return result;
      const equals = argString.indexOf('=');
      const optionPrefix = equals === -1 ? argString : argString.slice(0, equals);
      const explicitArg = equals === -1 ? null : argString.slice(equals + 1);
      for (const [optionString, action] of this._optionStringActions) {
        if (optionString.startsWith(optionPrefix)) {
          result.push({ action, optionString, explicitArg });
        }
      }
      return result;
    }

    const shortPrefix = argString.slice(0, 2);
    const shortExplicitArg = argString.slice(2);
    for (const [optionString, action] of this._optionStringActions) {
      if (optionString === shortPrefix) {
        result.push({ action, optionString, explicitArg: shortExplicitArg });
      } else if (this.allowAbbrev && optionString.startsWith(argString)) {
        result.push({ action, optionString, explicitArg: null });
      }
    }
    return result;
  }

  _getValue(action, argString) {
    if (!action.type) return argString;
    try {
      return action.type(argString);
    } catch (err) {
      if (!(err instanceof ValueError)) throw err;
      const typeName = action.type.pyName ?? action.type.name;
      throw new ArgumentError(
        action,
        `invalid ${typeName} value: ${pyRepr(argString)}`,
      );
    }
