/**
 * A faithful subset of `argparse.ArgumentParser`: long/short options, `=`
 * attached values, prefix abbreviation, the `--` separator, required-argument
 * checking, `-h/--help`, and the exact error text and exit codes CPython emits.
 */

import { basename } from 'node:path';

import { pyRepr } from '../python/builtins.mjs';
import { ValueError } from '../python/errors.mjs';
import { HelpAction, StoreAction } from './actions.mjs';
import { ArgumentError, ParserExit, argumentName } from './errors.mjs';
import { HelpFormatter } from './help-formatter.mjs';

const NEGATIVE_NUMBER = /^-\d+$|^-\d*\.\d+$/;

export class ArgumentParser {
  constructor({ prog, addHelp = true } = {}) {
    this.prog = prog ?? defaultProg();
    this.allowAbbrev = true;
    this._actions = [];
    this._optionStringActions = new Map();
    this._hasNegativeNumberOptionals = false;

    if (addHelp) {
      this.addArgument(['-h', '--help'], {
        action: 'help',
        help: 'show this help message and exit',
      });
    }
  }

  addArgument(optionStrings, options = {}) {
    const strings = Array.isArray(optionStrings) ? optionStrings : [optionStrings];
    const dest = options.dest ?? destFromOptionStrings(strings);
    const spec = { ...options, optionStrings: strings, dest };
    const action = options.action === 'help'
      ? new HelpAction(spec)
      : new StoreAction(spec);

    this._actions.push(action);
    for (const optionString of strings) {
      this._optionStringActions.set(optionString, action);
      if (NEGATIVE_NUMBER.test(optionString)) this._hasNegativeNumberOptionals = true;
    }
    return action;
  }

  parseArgs(argv) {
    const [namespace, extras] = this.parseKnownArgs(argv);
    if (extras.length > 0) {
      this.error(`unrecognized arguments: ${extras.join(' ')}`);
    }
    return namespace;
  }

  parseKnownArgs(argv = process.argv.slice(2)) {
    const namespace = Object.create(null);
    for (const action of this._actions) {
      if (!(action instanceof HelpAction)) namespace[action.dest] = null;
    }

    const seen = new Set();
    const extras = [];
    let index = 0;
    let afterSeparator = false;

    try {
      while (index < argv.length) {
        const argString = argv[index];

        // Everything from `--` onwards stops being an option, including the
        // separator itself -- with no positionals declared it all falls
        // through to the unrecognized-arguments report.
        if (afterSeparator || argString === '--') {
          afterSeparator = true;
          extras.push(argString);
          index += 1;
          continue;
