        const option = this._parseOptional(argString);
        if (option === null || option.action === null) {
          extras.push(argString);
          index += 1;
          continue;
        }

        index = this._consumeOptional(argv, index, option, namespace, seen, extras);
      }
    } catch (err) {
      if (err instanceof ArgumentError) this.error(err.message);
      throw err;
    }

    const missing = this._actions
      .filter((action) => action.required && !seen.has(action))
      .map((action) => argumentName(action));
