   * token (`-xyz` is `-x -y -z` when none of them take a value) and return the
   * index to resume from.
   */
  _consumeOptional(argv, startIndex, option, namespace, seen, extras) {
    let { action, optionString, sep, explicitArg } = option;
    const pending = [];
    let stop;

    for (;;) {
      if (explicitArg !== null) {
        if (action.nargs === 0) {
