          action = nextAction;
          optionString = nextOptionString;
          explicitArg = explicitArg.slice(1);
          if (!explicitArg) {
            sep = null;
            explicitArg = null;
          } else if (explicitArg[0] === '=') {
            sep = '=';
            explicitArg = explicitArg.slice(1);
          } else {
            sep = '';
          }
          continue;
        }
        pending.push([action, [explicitArg], optionString]);
        stop = startIndex + 1;
        break;
      }

      if (action.nargs === 0) {
        pending.push([action, [], optionString]);
        stop = startIndex + 1;
        break;
      }

      // The next token must be a plain value: not an option, and not the
      // `--` separator (argparse never matches it against an optional).
      const next = argv[startIndex + 1];
