/** argparse's default prog: the basename of the script that was invoked. */
function defaultProg() {
  return basename(process.argv[1] ?? 'node');
}

/** `format_usage()` collapses the trailing blank line the formatter emits. */
function stripTrailingBlank(usage) {
  return usage.replace(/\n+$/, '') + '\n';
}

