/**
 * Help/usage rendering, following argparse's `HelpFormatter` layout rules:
 * usage wrapping, the two-column option table and the help-column fallback for
 * long invocations.
 */

import { terminalColumns } from './terminal.mjs';
import { wrap } from './text-wrap.mjs';

const INDENT_INCREMENT = 2;
const DEFAULT_MAX_HELP_POSITION = 24;

export class HelpFormatter {
  constructor(prog) {
    this.prog = prog;
    this.width = terminalColumns() - 2;
    this.indentIncrement = INDENT_INCREMENT;
    this.maxHelpPosition = Math.min(
      DEFAULT_MAX_HELP_POSITION,
      Math.max(this.width - 20, INDENT_INCREMENT * 2),
    );
    this.currentIndent = 0;
  }

  /** `--a A`, or `[-h]` when the option is not required. */
  formatActionUsage(action) {
    let part = action.nargs === 0
      ? action.optionStrings[0]
      : `${action.optionStrings[0]} ${argsString(action)}`;
    if (!action.required) part = `[${part}]`;
    return part;
  }

  /** `-h, --help` / `--a A` -- the left column of the option table. */
  formatActionInvocation(action) {
    const joined = action.optionStrings.join(', ');
    return action.nargs === 0 ? joined : `${joined} ${argsString(action)}`;
  }

  /** The `usage: ...` block, already terminated by a blank line. */
  formatUsage(actions) {
    const prefix = 'usage: ';
    const optionParts = actions.map((action) => this.formatActionUsage(action));
    let usage = [this.prog, ...optionParts].filter((part) => part).join(' ');

    const textWidth = this.width - this.currentIndent;
    if (prefix.length + usage.length > textWidth) {
      let lines;
      if (prefix.length + this.prog.length <= 0.75 * textWidth) {
        const indent = ' '.repeat(prefix.length + this.prog.length + 1);
        lines = optionParts.length > 0
          ? getLines([this.prog, ...optionParts], indent, textWidth, prefix)
          : [this.prog];
      } else {
        const indent = ' '.repeat(prefix.length);
        lines = [this.prog, ...getLines(optionParts, indent, textWidth)];
      }
      usage = lines.join('\n');
    }

    return `${prefix}${usage}\n\n`;
  }

  /** The whole `--help` screen. */
  formatHelp(actions) {
    const helpPosition = Math.min(
      this.actionMaxLength(actions) + 2,
      this.maxHelpPosition,
    );

    const items = actions
      .map((action) => this.formatAction(action, helpPosition))
      .join('');

    let help = `${this.formatUsage(actions)}options:\n${items}\n`;
    help = help.replace(/\n\n\n+/g, '\n\n');
    return stripNewlines(help) + '\n';
  }

  actionMaxLength(actions) {
    const indent = this.currentIndent + this.indentIncrement;
    return actions.reduce(
      (longest, action) =>
        Math.max(longest, this.formatActionInvocation(action).length + indent),
      0,
    );
  }

  formatAction(action, helpPosition) {
    const indent = this.currentIndent + this.indentIncrement;
    const helpWidth = Math.max(this.width - helpPosition, 11);
    const actionWidth = helpPosition - indent - 2;
    const invocation = this.formatActionInvocation(action);

    let header;
    let indentFirst = 0;
    if (!action.help) {
      header = `${' '.repeat(indent)}${invocation}\n`;
    } else if (invocation.length <= actionWidth) {
      header = `${' '.repeat(indent)}${invocation.padEnd(actionWidth)}  `;
    } else {
      header = `${' '.repeat(indent)}${invocation}\n`;
      indentFirst = helpPosition;
    }

    const parts = [header];
    if (action.help && action.help.trim()) {
      const helpLines = wrap(action.help, helpWidth);
      parts.push(`${' '.repeat(indentFirst)}${helpLines[0]}\n`);
      for (const line of helpLines.slice(1)) {
        parts.push(`${' '.repeat(helpPosition)}${line}\n`);
